param([string]$Source='backend/SanSo.Api.V6/ProgramCanonicalV13.cs',[string]$Output='backend/SanSo.Api.V6/ProgramCanonicalV14.cs',[string]$Targets='backend/SanSo.Api.V6/Directory.Build.targets')
$ErrorActionPreference='Stop';$text=Get-Content -LiteralPath $Source -Raw -Encoding UTF8;if(-not$text.Contains('PostgresReportExportStoreV2')-or-not$text.Contains('V13ExportRequest')){throw 'API_V14_SOURCE_NOT_REPORT_V2'};$text=$text.Replace('api = "v13"','api = "v14"');[System.IO.File]::WriteAllText((Join-Path(Get-Location)$Output),$text,[System.Text.UTF8Encoding]::new($false));$t=Get-Content -LiteralPath $Targets -Raw -Encoding UTF8;$t=$t.Replace('ProgramCanonicalV13.cs','ProgramCanonicalV14.cs');[System.IO.File]::WriteAllText((Join-Path(Get-Location)$Targets),$t,[System.Text.UTF8Encoding]::new($false));"API_V14_ENTRYPOINT_GENERATED=$Output"
